  function reviewPanel(){const selected=state.selectedReviews.size;return `<details class="mcm-set-editor" ${state.reviews.length?"open":""}><summary class="button">Legacy originality review · ${state.reviews.length} unresolved</summary><p class="mcm-meta">These managed files are hidden from Gallery and have no active MED until you classify them. Review them by thumbnail in batches.</p><div class="mcm-bulk"><label><input type="checkbox" data-review-select-all> Select all ${state.reviews.length}</label><span>${selected} selected</span><button class="button" type="button" data-review-action="admit" ${selected?"":"disabled"}>Admit as my original media</button><button class="button" type="button" data-review-action="exclude" ${selected?"":"disabled"}>Exclude as external/reference</button><button class="button" type="button" data-review-action="defer" ${selected?"":"disabled"}>Decide later</button></div><div class="mcm-list">${state.reviews.map(record=>`<article class="mcm-card"><label class="mcm-select"><input type="checkbox" data-review-select="${esc(record.id)}" ${state.selectedReviews.has(record.id)?"checked":""}> Select</label>${preview(record)}<strong>${esc(record.original_filename)}</strong><span class="mcm-meta">Former ${esc(record.accession||"catalogue item")} · ${esc(record.mime_type)}</span></article>`).join("")||`<div class="cm-empty">No legacy media needs a decision.</div>`}</div></details>`}
