  async function finishUpload(job,record){
    job.recordId=record?.id||"";
    if(!job.recordId||job.destination!=="gallery")return record;
    await api(`/api/admin/media-library/${encodeURIComponent(job.recordId)}`,json("PATCH",{originality:"sixwell_original",asset_role:"creative_master",creator_credit:"Six.Well"}));
    await api("/api/admin/gallery",json("POST",{media_id:job.recordId}));
    await api(`/api/admin/gallery/${encodeURIComponent(job.recordId)}/publish`,{method:"POST"});
    return record;
  }
